// LeadStatsFunnel Cohort conversion, not a period ratio — cohort_leads is every client whose first-ever lead fell in the requested range; consulted_ever/ cased_ever count them regardless of when the consultation/case happened, even long after the range ends.
type LeadStatsFunnel struct {
	// AvgDaysConsultToCase Average gap between first consultation and first case, over clients who got both — not lead-to-case
	AvgDaysConsultToCase float32 `json:"avg_days_consult_to_case"`

	// AvgDaysToConsult Average gap between first lead and first consultation, over clients who got one
	AvgDaysToConsult float32 `json:"avg_days_to_consult"`
	CasedEver        int64   `json:"cased_ever"`
	CohortLeads      int64   `json:"cohort_leads"`
	ConsultedEver    int64   `json:"consulted_ever"`

	// FirstConsultOutcome What happened to each cohort client's FIRST consultation only (not "ever", unlike consulted_ever above) — mutually exclusive counts that sum to consulted_ever. This is the drop-off detail: of everyone who booked, how many actually showed up vs cancelled vs no-showed vs are still waiting on a future date.
	FirstConsultOutcome LeadStatsFunnelStage `json:"first_consult_outcome"`
}

// LeadStatsFunnelStage What happened to each cohort client's FIRST consultation only (not "ever", unlike consulted_ever above) — mutually exclusive counts that sum to consulted_ever. This is the drop-off detail: of everyone who booked, how many actually showed up vs cancelled vs no-showed vs are still waiting on a future date.
type LeadStatsFunnelStage struct {
	Cancelled int64 `json:"cancelled"`

	// Completed Showed up
	Completed int64 `json:"completed"`
	NoShow    int64 `json:"no_show"`

	// Scheduled Still in the future, not yet resolved
	Scheduled int64 `json:"scheduled"`
}

// LeadStatsSourceValue First-touch cohort attribution, not a raw lead count — key is leads.page of the client's first-ever lead ("" when the lead came without one, e.g. email); consulted_ever/cased_ever/revenue are followed with no date bound, same as LeadStatsFunnel.
